# Task module: simulation
# Authored by the simulator sub-agent (pmx-simulator), consuming
# skills/simulation-standards/ (SME-validated 2026-08-28). Reviewed by the
# SME as a diff at the simulation gate.
#
# Contract: define `task_targets`; never define gate targets — gate
# enforcement is generated by pipeline/compose.R. Available from the
# composer: `task_input` (analysis-declared settings), `analysis_id`,
# `upstream_gate` (name of the previous task's gate, or NULL).
#
# What this module wires together, in dependency order:
#   1. sim_fit — a deterministic verification refit of the declared nlmixr2
#      candidate (run 101). Cheap (seconds) and self-contained; a fit object
#      loaded back from another analysis's targets store breaks nlmixr2
#      post-processing ("parameter(s) are required for solving"), so the fit
#      is re-established here from the declared model file and dataset.
#   2. sim_translation_check — the mandatory equivalence check of the
#      per-analysis mrgsolve translation (declared in the analysis, e.g.
#      a project-supplied mrgsolve translation) against that fit. No scenario runs unless it
#      passes; on failure the translation is fixed, never the check.
#   3. sim_applicability — scenario dose and duration compared against the
#      fitted design, computed from data. Extrapolation without recorded SME
#      approval is a hard stop BEFORE any scenario runs (house guardrail 6).
#   4. sim_results — the declared scenarios, executed by the SME-validated
#      reference implementation with the declared seed and uncertainty tier.
#   5. sim_exposure_metrics / sim_figures — deliverables per house default 7.
#   6. simulation_package — the gate-package payload (rendered into the gate
#      record by the harness tools, mirroring qualification_package).
#
# Numbers flow only from executed code. This module contains NO analysis
# numerics (integrity batch 7, Codex round 8 finding 4): the exposure-metric
# definitions of house default 4, the unit identities and the median/interval
# summaries — including the per-time profile summary the figure draws — live
# in the manifested reference unit skills/simulation-standards/reference/
# exposure_metrics.R and are called here with DECLARED parameters (summary
# probabilities, quantile type, identity tolerance). Those parameters are
# stated below as the restatement of the house default and are reviewed with
# this diff at the gate.
#
# Two arms, chosen by the declared engine (task_input$engine), as in
# pipeline/tasks/qualification.R:
#   "nonmem"  the route using qualified NONMEM results and declared artifacts.
#             It reads the signed final run's stream, listing and parameter
#             file and its stored results (bm_res_<run>), and re-estimates
#             nothing. Compose-time validation of the declaration, each stop
#             naming its field; file targets over the translation, the run's
#             files and the three reference files it loads; then the estimates
#             by name from the parameter file (checked against their written
#             tokens), the run's own records as the equivalence design, the
#             declared scenario grid with per-kilogram doses (the approved
#             unit forms each amount), the applicability table against the
#             observed design, the equivalence check with an install
#             read-back, one reference_simulate call for every scenario with
#             the analysis seed, exposure metrics, the percentile-against-bound
#             table with its verdict columns from the approved comparison
#             unit, figures and the gate package. Every reference call sits
#             in a target command after load_reference; tools/
#             nonmem_simulation.R (ns_ functions) only reads, selects, places,
#             compares and binds. Each target splices only the declaration
#             fields it reads.
#   other     the arm below, unchanged.

if (identical(task_input$engine, "nonmem")) local({
  ti <- task_input
  refuse <- function(field, ...)
    stop("simulation: ", field, ": ", ..., " Declare it in analyses/", analysis_id,
         ".R; the module does not invent settings.", call. = FALSE)
  str1 <- function(x) is.character(x) && length(x) == 1L && !is.na(x) && nzchar(x)
  num1 <- function(x) is.numeric(x) && length(x) == 1L && is.finite(x)
  whole1 <- function(x) num1(x) && x == floor(x)
  rel_path <- function(x) str1(x) && !startsWith(x, "/") &&
    !grepl("(^|/)\\.\\.(/|$)", x)
  named_chr <- function(x) is.character(x) && length(x) && !is.null(names(x)) &&
    all(nzchar(names(x))) && !anyDuplicated(names(x)) && !anyNA(x) && all(nzchar(x))
  str_list <- function(x, nms) is.list(x) && setequal(names(x), nms) &&
    length(x) == length(nms) && all(vapply(x, str1, logical(1)))
  phases <- c("LD", "MD")

  # --- compose-time validation (plan Section 6.2 item 1) ---
  fields <- c("engine", "source", "translation", "parameter_map", "covariates",
              "reference_weight", "captures", "tolerance", "units", "grid_doses",
              "weight_points", "apgar_groups", "dose_cmt", "n", "grid", "post_dose_obs",
              "uncertainty", "seed", "metrics", "phase_metric", "summary_probs",
              "quantile_type", "auc_tolerance", "bounds", "bound_units", "applicability",
              "bootstrap_rows", "sensitivity", "figures", "out_dir")
  unknown <- setdiff(names(ti), fields)
  if (length(unknown)) refuse(paste(unknown, collapse = ", "), "unknown field(s).")
  absent <- setdiff(fields, names(ti))
  if (length(absent)) refuse(paste(absent, collapse = ", "), "missing.")
  src <- ti$source
  if (!str_list(src, c("run", "stream", "listing", "parameter_file")) ||
      !grepl("^[0-9A-Za-z_]+$", src[["run"]]) ||
      !all(vapply(src[c("stream", "listing", "parameter_file")], rel_path, logical(1))))
    refuse("source", "list(run = , stream = , listing = , parameter_file = ): one run name of ",
           "letters, digits and underscores and repository-relative paths without '..'.")
  for (f in c("translation", "out_dir"))
    if (!rel_path(ti[[f]])) refuse(f, "a repository-relative path without '..'.")
  task_input_file("simulation", "translation", ti$translation, single = TRUE)
  for (f in c("stream", "listing", "parameter_file"))
    task_input_file("simulation", paste0("source$", f), src[[f]], single = TRUE)
  pm <- ti$parameter_map
  if (!is.list(pm) || !length(pm) || is.null(names(pm)) || any(!nzchar(names(pm))) ||
      anyDuplicated(names(pm)))
    refuse("parameter_map", "a non-empty named list with unique engine names.")
  for (nm in names(pm)) {
    e <- pm[[nm]]
    ok <- is.list(e) && str1(e[["kind"]]) && e[["kind"]] %in% c("theta", "omega", "sigma") &&
      str1(e[["scale"]]) &&
      (if (identical(e[["kind"]], "theta")) str1(e[["model"]])
       else whole1(e[["model"]]) && e[["model"]] >= 1)
    if (!ok)
      refuse(paste0("parameter_map (", nm, ")"), "list(kind = theta, omega or sigma, model = ",
             "the parameter name for theta or the lower-triangle position for omega and ",
             "sigma, scale = one string).")
  }
  if (anyDuplicated(vapply(pm, function(e) paste(e[["kind"]], e[["model"]]), "")))
    refuse("parameter_map", "the (kind, model) pairs must be unique.")
  if (!named_chr(ti$covariates) || !"WT" %in% names(ti$covariates))
    refuse("covariates", "a named character vector (design column = model parameter) with WT.")
  if (!str_list(ti$reference_weight, c("param", "constant")))
    refuse("reference_weight", "list(param = , constant = ).")
  cap <- ti$captures
  if (!str_list(cap, c("observed", "clearance", "volume")))
    refuse("captures", "list(observed = , clearance = , volume = ).")
  if (!num1(ti$tolerance) || ti$tolerance <= 0 || ti$tolerance >= 1)
    refuse("tolerance", "one number in (0, 1).")
  if (!str_list(ti$units, c("time", "amt", "conc")))
    refuse("units", "list(time = , amt = , conc = ).")
  gd <- ti$grid_doses
  if (!is.list(gd) || !identical(names(gd), phases) ||
      !all(vapply(gd, function(x) is.numeric(x) && length(x) && all(is.finite(x)) &&
                    all(x > 0) && !is.unsorted(x, strictly = TRUE), logical(1))))
    refuse("grid_doses", "list(LD = , MD = ), each a non-empty increasing vector of positive doses.")
  wp <- ti$weight_points
  if (!named_chr(wp) || !all(grepl("^WT[0-9]{2}$", names(wp))) ||
      length(which(wp == ti$reference_weight$constant)) != 1L)
    refuse("weight_points", "a named character vector (WTnn = data-assembly label) holding the ",
           "reference_weight$constant label exactly once.")
  if (!is.character(ti$apgar_groups) || !length(ti$apgar_groups) ||
      !all(grepl("^APG[A-Z]+$", ti$apgar_groups)))
    refuse("apgar_groups", "a non-empty character vector matching ^APG[A-Z]+$.")
  if (!whole1(ti$dose_cmt) || ti$dose_cmt < 1) refuse("dose_cmt", "a whole number, 1 or more.")
  if (!whole1(ti$n) || ti$n < 500)
    refuse("n", "a whole number at or above 500; the house default may be raised, never lowered.")
  g <- ti$grid
  if (!is.list(g) || !setequal(names(g), c("start", "end", "delta")) ||
      !all(vapply(g, num1, logical(1))) || g$start != 0 || g$end <= g$start || g$delta <= 0)
    refuse("grid", "list(start = 0, end = , delta = ) of finite numbers.")
  if (!is.logical(ti$post_dose_obs) || length(ti$post_dose_obs) != 1L || is.na(ti$post_dose_obs))
    refuse("post_dose_obs", "one logical.")
  if (!identical(ti$uncertainty, "iiv"))
    refuse("uncertainty", "exactly \"iiv\" (MAP 4.4 item 4); 'full' is not wired and 'none' is ",
           "not declared. ESCALATE to the SME; do not substitute another tier.")
  if (!whole1(ti$seed)) refuse("seed", "one whole number.")
  # The implemented metrics are read from the reference (one source of truth).
  implemented_metrics <- local({
    load_reference("skills/simulation-standards",
                   "skills/simulation-standards/reference/exposure_metrics.R",
                   envir = environment())
    EXPOSURE_METRICS_IMPLEMENTED
  })
  if (!is.character(ti$metrics) || !length(ti$metrics) ||
      length(setdiff(ti$metrics, implemented_metrics)))
    refuse("metrics", "a subset of the exposure unit's implemented metrics (",
           paste(implemented_metrics, collapse = ", "), "); do not improvise one.")
  pmet <- ti$phase_metric
  if (!is.character(pmet) || !identical(names(pmet), phases) || !all(pmet %in% ti$metrics))
    refuse("phase_metric", "c(LD = , MD = ) naming declared metrics.")
  sp <- ti$summary_probs
  if (!is.numeric(sp) || length(sp) != 2L || any(!is.finite(sp)) || any(sp <= 0) ||
      any(sp >= 1) || sp[1] >= sp[2])
    refuse("summary_probs", "two increasing numbers in (0, 1).")
  if (!whole1(ti$quantile_type) || !ti$quantile_type %in% 1:9)
    refuse("quantile_type", "a stats::quantile type, 1 to 9.")
  if (!num1(ti$auc_tolerance) || ti$auc_tolerance < 0)
    refuse("auc_tolerance", "one non-negative number.")
  bnd <- ti$bounds
  if (!is.list(bnd) || !setequal(names(bnd), unique(pmet)) || length(bnd) != length(unique(pmet)) ||
      !all(vapply(bnd, function(b) is.numeric(b) && setequal(names(b), c("lower", "upper")) &&
                    length(b) == 2L && all(is.finite(b)) && b[["lower"]] < b[["upper"]],
                  logical(1))))
    refuse("bounds", "one c(lower = , upper = ) per phase metric, lower below upper.")
  if (!named_chr(ti$bound_units) || !setequal(names(ti$bound_units), names(bnd)))
    refuse("bound_units", "a named character vector with the names of bounds.")
  ap <- ti$applicability
  dose_keys <- unlist(lapply(phases, function(p) paste0(p, vapply(gd[[p]], format, "", trim = TRUE))))
  ae <- if (is.list(ap)) ap$approved_extrapolations
  if (!is.list(ap) || !setequal(names(ap), c("dose_rows", "horizon_row",
                                             "approved_extrapolations", "statements")) ||
      !is.list(ap$dose_rows) || !identical(names(ap$dose_rows), phases) ||
      !all(vapply(ap$dose_rows, function(r) is.character(r) && setequal(names(r), c("min", "max")) &&
                    length(r) == 2L && !anyNA(r), logical(1))) ||
      !str1(ap$horizon_row) || !named_chr(ap$statements) ||
      !(is.null(ae) || (is.character(ae) && (!length(ae) || named_chr(ae)))) ||
      !all(names(ae) %in% dose_keys) || !all(grepl("^A[0-9]+$", ae)))
    refuse("applicability", "list(dose_rows = list(LD = c(min = , max = ), MD = ...), ",
           "horizon_row = , approved_extrapolations = c(<phase><dose> = \"A<n>\"), possibly ",
           "empty, keyed by declared doses, statements = a named character vector).")
  if (!named_chr(ti$bootstrap_rows))
    refuse("bootstrap_rows", "a named character vector (row name = description).")
  # ponytail: the SME's B6-0a answers (Q-B6-1 (c), Q-B6-2 (c)) keep no
  # sensitivity scenario, so no exponent or bound scenario is built and a
  # member stops here rather than being ignored. Ceiling: no sensitivity rows;
  # upgrade path is plan Decisions 7 and 8 (ns_override_scenarios,
  # ns_override_identity, sim_override_check) through a planner delta.
  if (!is.list(ti$sensitivity) || length(ti$sensitivity))
    refuse("sensitivity", "list(): the SME's answers Q-B6-1 (c) and Q-B6-2 (c) keep no ",
           "sensitivity scenario; a member needs the override branch, which is not built.")
  fg <- ti$figures
  if (!is.list(fg) || !setequal(names(fg), c("bins", "ribbon")) || !whole1(fg$bins) ||
      fg$bins < 1 || !str1(fg$ribbon))
    refuse("figures", "list(bins = a whole number, ribbon = one string).")

  # --- targets (plan Section 3 Decision 5, under the B6-0a answers) ---
  run <- src[["run"]]
  res <- as.name(paste0("bm_res_", run))
  od <- ti$out_dir
  out <- function(f) file.path(od, f)
  file_target <- function(name, path)
    targets::tar_target_raw(name, call("identity", path), format = "file")
  ld <- function(ref) bquote(load_reference("skills/simulation-standards", .(as.name(ref)),
                                            envir = environment()))
  model_name <- paste0("sim_", run)
  compile_install <- bquote(ns_install(
    reference_sim_compile(ns_read_text(sim_translation_file), .(model_name)), sim_source))
  metric_files <- out(c("sim-exposure-metrics-by-subject.csv", "sim-exposure-metrics-summary.csv"))
  figure_files <- out(c(paste0("sim-conc-time-", phases, ".pdf"),
                        paste0("sim-metric-distributions-", phases, ".pdf")))

  task_targets <<- list(
    file_target("sim_translation_file", ti$translation),
    file_target("sim_stream_file", src[["stream"]]),
    file_target("sim_listing_file", src[["listing"]]),
    file_target("sim_ext_file", src[["parameter_file"]]),
    file_target("sim_mrgsolve_reference", "skills/simulation-standards/reference/mrgsolve_sim.R"),
    file_target("sim_exposure_reference",
                "skills/simulation-standards/reference/exposure_metrics.R"),
    file_target("sim_comparison_reference",
                "skills/simulation-standards/reference/bound_comparison.R"),

    # The estimates by name from the engine's parameter file, as written. The
    # map carries kind and model only (what ns_install and the read-back
    # read); the scale label is spliced into simulation_package, so a label
    # correction re-runs the package only (Decision 14).
    targets::tar_target_raw("sim_source", bquote(ns_source(
      estimates = ns_ext_row(sim_ext_file, .(names(pm))),
      version = nm_nonmem_version(sim_listing_file),
      map = .(lapply(pm, function(e) e[c("kind", "model")])),
      reference_weight = stats::setNames(
        ns_constant(da_weight_constants, .(ti$reference_weight$constant), "value_kg"),
        .(ti$reference_weight$param))))),

    # The run's own kept records and PRED: the equivalence design (E7).
    targets::tar_target_raw("sim_design", bquote(ns_fitted_design(
      .(res)$results$residuals, n_obs = .(res)$results$n_obs,
      covariates = .(ti$covariates), dose_cmt = .(ti$dose_cmt)))),

    targets::tar_target_raw("sim_scenarios", bquote(ns_scenarios(
      .(gd), ns_weight_points(da_weight_constants, .(wp)), .(ti$apgar_groups),
      n = .(ti$n), grid = .(g), dose_cmt = .(ti$dose_cmt),
      post_dose_obs = .(ti$post_dose_obs), weight_param = .(ti$covariates[["WT"]])))),

    # Stops before any scenario runs on a row outside the observed design
    # without recorded approval.
    targets::tar_target_raw("sim_applicability", bquote(ns_applicability(
      sim_scenarios$table, .(g$end), da_design_constants, .(ap$dose_rows),
      .(ap$horizon_row), .(ae)))),

    # E7 with the install read-back (E7 zeroes every random effect, so it
    # cannot see a misplaced OMEGA cell). A non-finite maximum relative error
    # is a stop: the unit's comparison drops a NaN row instead of failing it.
    targets::tar_target_raw("sim_translation_check", bquote({
      .(ld("sim_mrgsolve_reference"))
      mod <- .(compile_install)
      rb <- ns_install_readback(mod, sim_source)
      chk <- reference_sim_translate_check(mod, sim_design$design, sim_design$pred,
                                           observed = .(cap$observed),
                                           tolerance = .(ti$tolerance),
                                           covariates = .(names(ti$covariates)))
      if (!isTRUE(is.finite(chk[["max_rel_err"]])))
        stop("sim_translation_check: the maximum relative error is not finite; a NaN or ",
             "infinite prediction is not an equivalence. Fix the translation.", call. = FALSE)
      c(chk, list(n_dose_rows = sim_design$n_dose_rows, readback = rb))
    })),

    # Q-B6-7 (b): one reference_simulate call for every scenario, seeded once
    # with the analysis seed.
    targets::tar_target_raw("sim_results", bquote({
      sim_translation_check   # no scenario before the check passes
      sim_applicability       # nor outside the approved applicability domain
      .(ld("sim_mrgsolve_reference"))
      mod <- .(compile_install)
      ns_install_readback(mod, sim_source)
      ns_bind_runs(reference_simulate(mod, sim_scenarios$scenarios, seed = .(ti$seed),
                                      uncertainty = .(ti$uncertainty),
                                      observed = .(cap$observed)),
                   names(sim_scenarios$scenarios))
    })),

    # The run record's scenarios carry the amount the unit formed.
    targets::tar_target_raw("sim_exposure_metrics", bquote({
      .(ld("sim_exposure_reference"))
      scen <- ns_assert_record_amounts(sim_results$record$scenarios)
      by_subject <- reference_exposure_by_subject(
        sim_results$sim, scen, observed = .(cap$observed), time = "time",
        clearance = .(cap$clearance), volume = .(cap$volume),
        auc_tolerance = .(ti$auc_tolerance))
      summary <- reference_exposure_summary(by_subject, metrics = .(ti$metrics),
                                            units = .(ti$units), probs = .(sp),
                                            quantile_type = .(ti$quantile_type))
      dir.create(.(od), recursive = TRUE, showWarnings = FALSE)
      files <- .(metric_files)
      utils::write.csv(by_subject, files[1], row.names = FALSE)
      utils::write.csv(summary, files[2], row.names = FALSE)
      list(by_subject = by_subject, summary = summary, files = files,
           parameters = list(probs = .(sp), quantile_type = .(ti$quantile_type),
                             auc_tolerance = .(ti$auc_tolerance)))
    })),

    # Percentile beside the declared bound; the verdict columns come from the approved unit.
    targets::tar_target_raw("sim_bounds", bquote({
      .(ld("sim_comparison_reference"))
      tab <- ns_bound_table(sim_exposure_metrics$summary, sim_scenarios$table, .(pmet),
                            .(bnd), .(ti$bound_units))
      tab <- cbind(tab, reference_bound_verdict(tab$lower, tab$upper, tab$bound_lower,
                                                tab$bound_upper))
      dir.create(.(od), recursive = TRUE, showWarnings = FALSE)
      utils::write.csv(tab, .(out("sim-bounds.csv")), row.names = FALSE)
      list(table = tab, file = .(out("sim-bounds.csv")))
    })),

    # Per phase, in scenario-table order, one concentration-time panel and one
    # metric-distribution panel per scenario; one PDF of each per phase.
    targets::tar_target_raw("sim_figures", bquote({
      .(ld("sim_exposure_reference"))
      tab <- sim_scenarios$table
      sim <- sim_results$sim
      bs <- sim_exposure_metrics$by_subject
      paths <- .(stats::setNames(figure_files, c(paste0("conc_", phases),
                                                 paste0("metric_", phases))))
      dir.create(.(od), recursive = TRUE, showWarnings = FALSE)
      for (ph in .(phases)) {
        sc <- tab$SCENARIO[tab$phase == ph]
        prof <- lapply(sc, function(s) ns_profile_plot(
          reference_profile_summary(sim[sim$SCENARIO == s, ], observed = .(cap$observed),
                                    time = "time", probs = .(sp),
                                    quantile_type = .(ti$quantile_type)),
          s, .(ti$units), .(fg$ribbon)))
        met <- lapply(sc, function(s) ns_metric_plot(bs[bs$SCENARIO == s, ], .(ti$metrics), s,
                                                     .(fg$bins)))
        if (length(prof) != length(which(tab$phase == ph)) ||
            length(met) != length(which(tab$phase == ph)))
          stop("sim_figures: the ", ph, " panel count differs from its scenario count.",
               call. = FALSE)
        nm_write_panels(prof, paths[[paste0("conc_", ph)]])
        nm_write_panels(met, paths[[paste0("metric_", ph)]])
      }
      unname(paths)
    }), format = "file"),

    targets::tar_target_raw("simulation_package", bquote({
      # Every simulation target is named here, so the store-staleness check
      # of the gate package sees all of them.
      sim_mrgsolve_reference; sim_exposure_reference; sim_comparison_reference; sim_design
      rec <- sim_results$record
      tab <- sim_scenarios$table
      chk <- sim_translation_check
      art <- function(artifact, path, source)
        data.frame(artifact = artifact, path = nq_relative_path(path), source = source,
                   stringsAsFactors = FALSE)
      grid <- .(g)
      tables <- list(
        "Run record" = data.frame(
          engine = rec$engine, engine_version = rec$version, seed = rec$seed,
          uncertainty_tier = rec$uncertainty, observed = rec$observed,
          seeding = "one reference_simulate call for every scenario, seeded once with the analysis seed",
          estimation_engine = "NONMEM", estimation_engine_version = sim_source$version,
          stringsAsFactors = FALSE),
        "Final model source" = data.frame(
          run = .(run), role = c("stream", "listing", "parameter file", "translation"),
          path = nq_relative_path(c(sim_stream_file, sim_listing_file, sim_ext_file,
                                    sim_translation_file)),
          bound_by = c(rep("the estimation gate's artifact rows", 3L),
                       "this gate: the equations are reviewed by the SME"),
          stringsAsFactors = FALSE),
        "Parameters installed in the translation" = data.frame(
          engine_name = names(sim_source$map),
          model_target = chk$readback$model_target[match(names(sim_source$map),
                                                         chk$readback$engine_name)],
          kind = vapply(sim_source$map, function(e) e[["kind"]], "", USE.NAMES = FALSE),
          scale = .(vapply(pm, function(e) e[["scale"]], "", USE.NAMES = FALSE)),
          value_from_parameter_file = as.numeric(sim_source$estimates),
          readback_identical = chk$readback$readback_identical[match(names(sim_source$map),
                                                                     chk$readback$engine_name)],
          stringsAsFactors = FALSE),
        "Translation equivalence check (E7)" = data.frame(
          observation_rows = chk$n, dose_rows = chk$n_dose_rows, max_rel_err = chk$max_rel_err,
          tolerance = chk$tolerance, covariates = .(paste(names(ti$covariates), collapse = ", ")),
          stringsAsFactors = FALSE),
        "Weight points" = data.frame(
          label = .(names(wp)), data_assembly_row = .(unname(wp)),
          weight_kg = tab$weight_kg[match(.(names(wp)), tab$weight_point)],
          stringsAsFactors = FALSE),
        "Scenario definitions" = data.frame(
          tab[c("SCENARIO", "kind", "phase", "dose_mg_per_kg", "weight_point", "weight_kg",
                "apgar_group")],
          amount_formed_by_unit = vapply(tab$SCENARIO, function(s)
            rec$scenarios[[s]][["regimen"]][["amt"]], numeric(1), USE.NAMES = FALSE),
          amount_unit = .(ti$units$amt), cmt = .(ti$dose_cmt), n = .(ti$n),
          grid = paste0(grid[["start"]], " to ", grid[["end"]], " by ", grid[["delta"]]),
          post_dose_obs = .(ti$post_dose_obs), overrides = tab$overrides,
          stringsAsFactors = FALSE),
        "Applicability against the observed design" = sim_applicability,
        "Applicability statements" = data.frame(
          statement = .(names(ap$statements)), text = .(unname(ap$statements)),
          stringsAsFactors = FALSE),
        "Exposure metrics" = sim_exposure_metrics$summary,
        "Percentile against bound" = sim_bounds$table,
        "Bootstrap intervals for typical clearance and volume" =
          ns_bootstrap_rows(qual_bootstrap$parameter_table, .(ti$bootstrap_rows)))
      artifacts <- rbind(
        art("translation (model text, for equation review)", sim_translation_file,
            "file target sim_translation_file; passed the equivalence check"),
        art("final-run stream", sim_stream_file, "file target sim_stream_file"),
        art("final-run listing", sim_listing_file, "file target sim_listing_file"),
        art("final-run parameter file", sim_ext_file, "file target sim_ext_file"),
        art("exposure metrics by subject", sim_exposure_metrics$files[1],
            "target sim_exposure_metrics (simulation-standards exposure_metrics)"),
        art("exposure metrics summary", sim_exposure_metrics$files[2],
            "target sim_exposure_metrics (simulation-standards exposure_metrics)"),
        art("percentile against bound", sim_bounds$file,
            "target sim_bounds (simulation-standards bound_comparison)"),
        art(basename(sim_figures), sim_figures,
            "target sim_figures (simulation-standards exposure_metrics)"))
      notes <- c(
        list(
          authored_note("Every number in the tables above is read from executed targets: the engine's parameter file and listing, the results reader's records, the approved simulation units and the declaration; nothing is transcribed by hand."),
          authored_note("All three gates of the compile-and-simulate discipline ran: compile, the equivalence check against the fitted model's own records with the install read-back, and physical checks on every scenario output."),
          authored_note("The interindividual-variability tier simulates between-subject variability only: parameter (estimation) uncertainty is not propagated, and the bootstrap intervals are shown beside the results for the SME's judgement whether a marginal result could change. Residual error is not sampled."),
          authored_note("auc_0_inf is the amount divided by the subject's clearance, exact for a linear one-compartment model."),
          authored_note("Each amount is formed by the approved unit from the declared dose per kilogram and the weight point's weight; this module computes no amount."),
          authored_note("The verdict columns of the percentile-against-bound table are computed by the approved bound_comparison unit from each percentile and its declared bound, a percentile equal to its bound passing; the SME confirms them at the gate, and a disposition sits beside a computed verdict, never in its place (MAP 4.3.4)."),
          authored_note("The tails of the maintenance exposure distribution depend on the precision of the clearance variance; where the qualification stage recorded that variance as imprecise, the tails are read with that flag."),
          evidence_note("Analysis seed, as recorded in the run record", rec$seed),
          evidence_note("Uncertainty tier, as recorded in the run record", rec$uncertainty),
          evidence_note(paste0("Subjects simulated per scenario (in the row order of the ",
                               "scenario-definitions table)"),
                        vapply(tab$SCENARIO, function(s) rec$scenarios[[s]][["n"]], numeric(1),
                               USE.NAMES = FALSE))),
        lapply(.(unname(ap$statements)), authored_note))
      list(analysis = .(analysis_id), task = "simulation", tables = tables,
           artifacts = artifacts, notes = notes)
    }))
  )
  stopifnot(!anyDuplicated(vapply(task_targets, function(t) t$settings$name, "")))
}) else local({
  ti <- task_input

  # --- compose-time validation of the analysis-declared input contract -----
  need <- c("model", "model_object", "metadata_object", "data", "est", "refit_budget", "translation",
            "tolerance", "scenarios", "uncertainty", "units", "metrics",
            "summary_probs", "quantile_type", "auc_tolerance",
            "seed", "out_dir")
  missing_in <- setdiff(need, names(ti))
  if (length(missing_in)) {
    stop("Analysis declaration for the simulation task is missing: ",
         paste(missing_in, collapse = ", "),
         ". Declare them in analyses/", analysis_id, ".R; the module does ",
         "not invent settings at run time.", call. = FALSE)
  }
  for (field in c("model", "data", "translation"))
    task_input_file("simulation", field, ti[[field]], single = TRUE)
  for (field in c("model_object", "metadata_object")) {
    name <- ti[[field]]
    if (!is.character(name) || length(name) != 1L || is.na(name) ||
        !grepl("^[A-Za-z][A-Za-z0-9._]*$", name))
      stop("simulation: ", field, " must name an object defined by the model file.", call. = FALSE)
  }
  if (identical(ti$uncertainty, "full")) {
    stop("Uncertainty tier 'full' is not yet wired: skills/simulation-",
         "standards/reference/uncertainty.R is available as a separately reviewed method ",
         "but this module does not yet dispatch through it. ",
         "ESCALATE to the SME; do not substitute another tier to make ",
         "progress.", call. = FALSE)
  }
  if (!identical(ti$uncertainty, "none") && !identical(ti$uncertainty, "iiv")) {
    stop("Unknown uncertainty tier '", ti$uncertainty,
         "'; declared tiers are none, iiv, full.", call. = FALSE)
  }
  if (!is.list(ti$scenarios) || length(ti$scenarios) == 0 ||
      is.null(names(ti$scenarios)) || any(!nzchar(names(ti$scenarios)))) {
    stop("Scenarios must be a non-empty named list; scenario names appear ",
         "verbatim in outputs and the gate package.", call. = FALSE)
  }
  for (nm in names(ti$scenarios)) {
    sc <- ti$scenarios[[nm]]
    if (is.null(sc$regimen$amt) || is.null(sc$regimen$cmt) || is.null(sc$n) ||
        (is.null(sc$grid) && is.null(sc$times))) {
      stop("Scenario '", nm, "' must declare regimen$amt, regimen$cmt, n, ",
           "and a sampling grid (grid or times); counts and grids are ",
           "declared in the analysis, never chosen at run time.",
           call. = FALSE)
    }
  }
  # Metrics are defined in the reference unit; a metric declared without a
  # reference definition is a stop, not an invitation to improvise one. The
  # implemented set is read from the reference itself (one source of truth).
  implemented_metrics <- local({
    load_reference("skills/simulation-standards",
                   "skills/simulation-standards/reference/exposure_metrics.R",
                   envir = environment())
    EXPOSURE_METRICS_IMPLEMENTED
  })
  unknown_metrics <- setdiff(ti$metrics, implemented_metrics)
  if (length(unknown_metrics)) {
    stop("Declared exposure metric(s) with no reference definition in ",
         "skills/simulation-standards/reference/exposure_metrics.R: ",
         paste(unknown_metrics, collapse = ", "),
         ". A reference implementation is authored and SME-validated first; ",
         "do not improvise one.", call. = FALSE)
  }
  # Summary parameters are SME-declared in the analysis (review round 8): the
  # interval probabilities, the stats::quantile type and the relative
  # tolerance of the unit identities. Validated for shape here; their values
  # are the analysis's, never this module's.
  summary_probs <- ti$summary_probs
  quantile_type <- ti$quantile_type
  auc_tolerance <- ti$auc_tolerance
  if (!is.numeric(summary_probs) || length(summary_probs) != 2L ||
      any(!is.finite(summary_probs)) || summary_probs[1] >= summary_probs[2]) {
    stop("summary_probs must be two increasing probabilities declared in ",
         "analyses/", analysis_id, ".R.", call. = FALSE)
  }
  if (!is.numeric(quantile_type) || length(quantile_type) != 1L ||
      !quantile_type %in% 1:9) {
    stop("quantile_type must be a stats::quantile type (1..9) declared in ",
         "analyses/", analysis_id, ".R.", call. = FALSE)
  }
  if (!is.numeric(auc_tolerance) || length(auc_tolerance) != 1L ||
      !is.finite(auc_tolerance) || auc_tolerance < 0) {
    stop("auc_tolerance must be a single non-negative number declared in ",
         "analyses/", analysis_id, ".R.", call. = FALSE)
  }
  # Interval column names follow the declared probabilities (0.05 -> p5,
  # 0.95 -> p95), so the gate table keeps its recorded shape.
  prob_col <- function(p) paste0("p", format(100 * p, trim = TRUE))
  lower_col <- prob_col(summary_probs[1])
  upper_col <- prob_col(summary_probs[2])

  gate_dep <- if (is.null(upstream_gate)) NULL else as.name(upstream_gate)

  task_targets <<- list(

    # Input files tracked as file targets: an edited model definition,
    # dataset, or translation text invalidates everything downstream.
    targets::tar_target_raw("sim_model_def_file",
                            call("identity", ti$model), format = "file"),
    targets::tar_target_raw("sim_data_file",
                            call("identity", ti$data), format = "file"),
    targets::tar_target_raw("sim_translation_file",
                            call("identity", ti$translation), format = "file"),

    # 1. Deterministic verification refit of the declared candidate. The
    # upstream gate is a dependency here, so no simulation work starts
    # before that gate is signed; everything below depends on sim_fit.
    targets::tar_target_raw(
      "sim_fit",
      as.call(c(quote(`{`), gate_dep,
                list(bquote({
                  source(sim_model_def_file, local = TRUE)
                  da <- read_external_dataset(sim_data_file)
                  model <- get(.(ti$model_object), envir = environment(), inherits = FALSE)
                  meta <- get(.(ti$metadata_object), envir = environment(), inherits = FALSE)
                  rec <- run_candidate(model, meta, da,
                                       est = .(ti$est),
                                       budget_used = .(ti$refit_budget$used),
                                       budget_max  = .(ti$refit_budget$max))
                  if (rec$failed) {
                    stop("Verification refit of run ", rec$meta$run,
                         " failed: ", rec$error, call. = FALSE)
                  }
                  if (!rec$converged) {
                    stop("Verification refit of run ", rec$meta$run,
                         " did not converge; refusing to check the ",
                         "translation against an unconverged fit. ESCALATE.",
                         call. = FALSE)
                  }
                  rec
                }))))),

    # 2. Mandatory translation-equivalence check (house control 1). The
    # design is the fit's own: dose records from the assembled dataset with
    # the same C-flag exclusion run_candidate applies, observation records
    # taken from the fit itself so the keys can only be the fit's keys.
    targets::tar_target_raw(
      "sim_translation_check",
      bquote({
        load_reference("skills/simulation-standards",
                       "skills/simulation-standards/reference/mrgsolve_sim.R",
                       envir = environment())
        source(sim_translation_file, local = TRUE)
        mod <- sim_101_model_from_fit(sim_fit$fit,
                                      compile = reference_sim_compile)
        da <- read_external_dataset(sim_data_file)
        # Record selection through the one harness classifier
        # (tools/record_selection.R), the same rule the fit used.
        kept <- da[harness_kept_record(da$C), ]
        doses <- kept[harness_is_dose(kept$EVID), c("ID", "TIME", "AMT")]
        fitdf <- as.data.frame(sim_fit$fit)
        design <- rbind(
          data.frame(ID = as.integer(as.character(doses$ID)),
                     TIME = doses$TIME, EVID = 1L, AMT = doses$AMT, CMT = 1L),
          data.frame(ID = as.integer(as.character(fitdf$ID)),
                     TIME = fitdf$TIME, EVID = 0L, AMT = 0, CMT = 0L))
        pred <- data.frame(ID = as.integer(as.character(fitdf$ID)),
                           TIME = fitdf$TIME, PRED = fitdf$PRED)
        chk <- reference_sim_translate_check(mod, design, pred,
                                             observed = "CP",
                                             tolerance = .(ti$tolerance))
        c(chk, list(n_dose_rows = nrow(doses),
                    checked_at = format(Sys.time(), tz = "UTC", usetz = TRUE)))
      })),

    # 3. Applicability of the declared scenarios against the fitted design
    # (house guardrail 6): dose within the fitted dose range, horizon within
    # the studied duration. Computed from data, and a hard stop before any
    # scenario runs when a dimension extrapolates without recorded SME
    # approval. Route/formulation and population are categorical and are
    # addressed in the gate-package notes instead.
    targets::tar_target_raw(
      "sim_applicability",
      bquote({
        da <- read_external_dataset(sim_data_file)
        kept <- da[harness_kept_record(da$C), ]
        if (sim_fit$n_obs != sum(harness_is_observation(kept$EVID))) {
          stop("Fit record and dataset disagree on observation count (",
               sim_fit$n_obs, " vs ", sum(kept$EVID == 0),
               "); the applicability ranges would not describe the fitted ",
               "design.", call. = FALSE)
        }
        fitted_dose <- range(kept$AMT[kept$EVID == 1])
        fitted_tmax <- max(kept$TIME[kept$EVID == 0])
        scen <- .(ti$scenarios)
        appl <- do.call(rbind, lapply(names(scen), function(nm) {
          sc <- scen[[nm]]
          horizon <- if (!is.null(sc$times)) max(sc$times) else sc$grid$end
          rbind(
            data.frame(SCENARIO = nm, dimension = "dose (mg)",
                       scenario_value = sc$regimen$amt,
                       fitted_min = fitted_dose[1],
                       fitted_max = fitted_dose[2],
                       within_fitted = sc$regimen$amt >= fitted_dose[1] &
                                       sc$regimen$amt <= fitted_dose[2]),
            data.frame(SCENARIO = nm, dimension = "duration (h)",
                       scenario_value = horizon,
                       fitted_min = 0, fitted_max = fitted_tmax,
                       within_fitted = horizon <= fitted_tmax))
        }))
        if (any(!appl$within_fitted)) {
          bad <- appl[!appl$within_fitted, ]
          stop("Scenario extrapolates beyond the fitted applicability ",
               "domain (", paste(unique(bad$SCENARIO), collapse = ", "),
               ": ", paste(unique(bad$dimension), collapse = ", "),
               "). Explicit SME approval recorded in the analysis plan or an ",
               "amendment is required BEFORE such a run; surface this at the ",
               "gate instead of running it.", call. = FALSE)
        }
        appl
      })),

    # 4. The declared scenarios through the SME-validated, self-gating
    # reference implementation. Depends on the passed equivalence check and
    # the in-domain applicability table; the seed is the declared one and is
    # echoed into the returned run record.
    targets::tar_target_raw(
      "sim_results",
      bquote({
        sim_translation_check   # no scenario before the check passes
        sim_applicability       # nor outside the applicability domain
        load_reference("skills/simulation-standards",
                       "skills/simulation-standards/reference/mrgsolve_sim.R",
                       envir = environment())
        source(sim_translation_file, local = TRUE)
        mod <- sim_101_model_from_fit(sim_fit$fit,
                                      compile = reference_sim_compile)
        reference_simulate(mod,
                           scenarios   = .(ti$scenarios),
                           seed        = .(ti$seed),
                           uncertainty = .(ti$uncertainty),
                           observed    = "CP")
      })),

    # 5a. Exposure metrics (house default 4, single-dose set) through the
    # manifested reference unit exposure_metrics, on CP — the individual
    # model-predicted concentration; the iiv tier simulates individual
    # parameters, not noisy observations. Metrics are computed per subject
    # and summarised as median [lower, upper] at the declared probabilities
    # and quantile type. Definitions and the two unit identities
    # (AUC(0-tlast) <= AUC(0-inf); Cmax <= amt / V_i) live in the reference
    # and are documented in its header; this target only passes declared
    # parameters and writes the results.
    targets::tar_target_raw(
      "sim_exposure_metrics",
      bquote({
        load_reference("skills/simulation-standards",
                       "skills/simulation-standards/reference/exposure_metrics.R",
                       envir = environment())
        sim  <- sim_results$sim
        scen <- sim_results$record$scenarios
        un   <- .(ti$units)
        by_subject <- reference_exposure_by_subject(
          sim, scen, observed = "CP", time = "time",
          clearance = "CL", volume = "V",
          auc_tolerance = .(auc_tolerance))
        summary <- reference_exposure_summary(
          by_subject, metrics = .(ti$metrics), units = un,
          probs = .(summary_probs), quantile_type = .(quantile_type))
        # The gate table keeps its recorded shape (SCENARIO | metric | unit |
        # n | median | p5 | p95): interval columns named from the declared
        # probabilities, the probability echo columns dropped (they are
        # recorded once in `parameters` and the evidence note).
        names(summary)[names(summary) == "lower"] <- .(lower_col)
        names(summary)[names(summary) == "upper"] <- .(upper_col)
        summary$p_lower <- NULL
        summary$p_upper <- NULL
        out_dir <- .(ti$out_dir)
        dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)
        files <- file.path(out_dir, c("sim-exposure-metrics-by-subject.csv",
                                      "sim-exposure-metrics-summary.csv"))
        utils::write.csv(by_subject, files[1], row.names = FALSE)
        utils::write.csv(summary, files[2], row.names = FALSE)
        list(by_subject = by_subject, summary = summary, units = un,
             files = files,
             parameters = list(probs = .(summary_probs),
                               quantile_type = .(quantile_type),
                               auc_tolerance = .(auc_tolerance)))
      })),

    # 5b. Deliverable figures (house default 7): concentration-time figure
    # (median with 5th/95th ribbon when more than one subject is simulated,
    # single curve otherwise) and exposure-metric distribution plots. All
    # figures are on the linear scale, so the log-axis predose-zero rule is
    # not triggered.
    targets::tar_target_raw(
      "sim_figures",
      bquote({
        load_reference("skills/simulation-standards",
                       "skills/simulation-standards/reference/exposure_metrics.R",
                       envir = environment())
        out_dir <- .(ti$out_dir)
        dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)
        sim <- sim_results$sim
        rec <- sim_results$record
        un  <- .(ti$units)
        files <- character(0)
        for (nm in names(rec$scenarios)) {
          d <- sim[sim$SCENARIO == nm, ]
          n_sub <- length(unique(d$ID))
          # Per-time profile summary from the reference unit, at the same
          # declared probabilities and quantile type as the metric table.
          q <- reference_profile_summary(d, observed = "CP", time = "time",
                                         probs = .(summary_probs),
                                         quantile_type = .(quantile_type))
          p <- ggplot2::ggplot(q, ggplot2::aes(time, median))
          if (n_sub > 1) {
            p <- p + ggplot2::geom_ribbon(
              ggplot2::aes(ymin = lower, ymax = upper),
              fill = "grey70", alpha = 0.6)
          }
          p <- p + ggplot2::geom_line(linewidth = 0.8) +
            ggplot2::labs(
              x = paste0("Time (", un$time, ")"),
              y = paste0("Simulated concentration (", un$conc, ")"),
              title = nm,
              subtitle = paste0(
                "n = ", n_sub, ", uncertainty = ", rec$uncertainty,
                if (n_sub > 1) ", median with 5th-95th percentile ribbon"
                else ", single typical curve",
                ", seed = ", rec$seed)) +
            ggplot2::theme_bw()
          f <- file.path(out_dir, paste0("sim-conc-time-", nm, ".pdf"))
          ggplot2::ggsave(f, p, width = 7, height = 5)
          files <- c(files, f)

          bs <- sim_exposure_metrics$by_subject
          bs <- bs[bs$SCENARIO == nm, ]
          if (nrow(bs) > 1) {
            su <- sim_exposure_metrics$summary
            long <- do.call(rbind, lapply(.(ti$metrics), function(m)
              data.frame(metric = paste0(m, " (",
                                         su$unit[su$metric == m][1], ")"),
                         value = bs[[m]])))
            ph <- ggplot2::ggplot(long, ggplot2::aes(value)) +
              ggplot2::geom_histogram(bins = 30, fill = "grey70",
                                      color = "grey30") +
              ggplot2::facet_wrap(~metric, scales = "free") +
              ggplot2::labs(x = NULL, y = "Subjects", title = nm,
                            subtitle = paste0("Exposure-metric distributions, n = ",
                                              nrow(bs), ", seed = ", rec$seed)) +
              ggplot2::theme_bw()
            fh <- file.path(out_dir,
                            paste0("sim-metric-distributions-", nm, ".pdf"))
            ggplot2::ggsave(fh, ph, width = 8, height = 3.5)
            files <- c(files, fh)
          }
        }
        files
      })),

    # 6. Gate-package payload. Rendered into gates/<ID>/simulation.md by the
    # harness gate-package tool (as with qualification_package); this target
    # only assembles tool-computed values, declared settings, and prose.
    targets::tar_target_raw(
      "simulation_package",
      bquote({
        load_reference("skills/simulation-standards",
                       "skills/simulation-standards/reference/mrgsolve_sim.R",
                       envir = environment())
        source(sim_translation_file, local = TRUE)
        rec <- sim_results$record
        scen_tab <- do.call(rbind, lapply(names(rec$scenarios), function(nm) {
          sc <- rec$scenarios[[nm]]
          data.frame(
            SCENARIO = nm,
            amt = sc$regimen$amt, cmt = sc$regimen$cmt,
            ii = if (is.null(sc$regimen$ii)) NA_real_ else sc$regimen$ii,
            addl = if (is.null(sc$regimen$addl)) NA_real_ else sc$regimen$addl,
            n = sc$n,
            grid = if (!is.null(sc$times)) {
              paste0("times: ", paste(sc$times, collapse = ", "))
            } else {
              paste0(sc$grid$start, "-", sc$grid$end, " by ", sc$grid$delta)
            })
        }))
        tables <- list(
          "Run record" = data.frame(
            engine = rec$engine,
            engine_version = rec$version,
            estimation_engine = paste0("nlmixr2est ",
              as.character(utils::packageVersion("nlmixr2est"))),
            seed = rec$seed,
            uncertainty_tier = rec$uncertainty,
            observed = rec$observed),
          "Scenario definitions (declared)" = scen_tab,
          "Verification refit of run 101" = data.frame(
            run = sim_fit$meta$run, est = sim_fit$est,
            converged = sim_fit$converged,
            ofv = round(sim_fit$ofv, 3), aic = round(sim_fit$aic, 3),
            n_id = sim_fit$n_id, n_obs = sim_fit$n_obs,
            runtime_s = sim_fit$runtime_s),
          "Translation equivalence check" = data.frame(
            n_obs_rows = sim_translation_check$n,
            max_rel_err = signif(sim_translation_check$max_rel_err, 3),
            tolerance = sim_translation_check$tolerance,
            n_dose_rows = sim_translation_check$n_dose_rows,
            checked_at = sim_translation_check$checked_at),
          "Fit-to-engine parameter mapping" =
            sim_101_parameter_table(sim_fit$fit),
          "Applicability vs fitted design" = sim_applicability,
          "Exposure metrics, median [5th, 95th]" = sim_exposure_metrics$summary)
        artifacts <- data.frame(
          artifact = c("mrgsolve translation (model text, for equation review)",
                       "exposure metrics by subject",
                       "exposure metrics summary",
                       basename(sim_figures)),
          path = c(sim_translation_file, sim_exposure_metrics$files,
                   sim_figures),
          source = c("authored per analysis; passed equivalence check",
                     rep("targets store: sim_exposure_metrics", 2),
                     rep("targets store: sim_figures",
                         length(sim_figures))))
        validated <- sim_reference_validated()
        # Gate notes are typed (tools/evidence_notes.R): every value that came
        # out of executed code is an evidence_note() bound to the expression
        # that produced it — the value is evaluated here and rendered by the
        # same deterministic renderer as the gate tables, never transcribed
        # into prose. Prose that carries no computed value is authored_note()
        # and renders outside the digested envelope.
        notes <- list(
          evidence_note(
            paste0("Reference implementation skills/simulation-standards/",
                   "reference/mrgsolve_sim.R validation status, checked at ",
                   "run time"),
            if (validated) "SME-VALIDATED (signed record)"
            else "NOT SME-VALIDATED"),
          authored_note("All three gates of the compile-and-simulate discipline ran: compile, equivalence check against the fitted model, and physical checks on every scenario output (finite, non-negative, drug reaches the observed compartment)."),
          evidence_note(
            paste0("Subjects simulated per scenario (n, in the row order of ",
                   "the scenario-definitions table above)"),
            scen_tab$n),
          authored_note(paste0(
            "Interpretation for SME confirmation: the analysis declaration's ",
            "loose 'n_rep' was structured as a subject count at the ",
            "uncertainty tier recorded above, not as replicate runs. House ",
            "default for a low-MODEL_RISK analysis is tier 'none' with a ",
            "single typical subject, under which repeated replicates would be ",
            "identical curves; the declared count therefore implies the ",
            "question needs variability, and it is the house default count ",
            "for exposure-metric distributions in ",
            "skills/simulation-standards.")),
          evidence_note(
            paste0("Uncertainty tier executed (parameter uncertainty is ",
                   "propagated only at tier 'full')"),
            rec$uncertainty),
          authored_note("Parameter (estimation) uncertainty is NOT propagated: tier 'iiv' simulates interindividual variability only, and tier 'full' is blocked because this module does not yet dispatch through reference/uncertainty.R (the reference itself is SME-validated, 2026-09-01). Residual error is not sampled (individual predicted concentrations, not noisy observations)."),
          authored_note("AUC(0-inf) is computed as amt / CL_i (subject's apparent clearance), exact for this linear one-compartment model; the skill's house defaults name the metric without fixing an extrapolation method, so the SME is asked to confirm this definition. Exposure metrics, unit identities and profile summaries come from the manifested reference unit exposure_metrics (skills/simulation-standards/reference/exposure_metrics.R), called with the declared parameters recorded in the evidence note below."),
          evidence_note(
            paste0("Declared summary parameters passed to the exposure_metrics ",
                   "reference (probabilities, stats::quantile type, identity ",
                   "tolerance)"),
            unlist(sim_exposure_metrics$parameters)),
          authored_note("Applicability: dose and duration are inside the fitted design (table above). Route and formulation match the fitted study (single oral dose); the simulated population is the fitted population itself (run 101 has no covariates), so no population extrapolation arises."),
          authored_note("All figures are linear-scale; the log-axis predose-zero drop rule is not triggered."),
          evidence_note("Analysis seed, as recorded in the run record",
                        rec$seed),
          authored_note("Seed policy: one seed for the analysis, fixed in the analysis declaration and echoed in every output record; the value itself is the evidence note above."))
        list(analysis = .(analysis_id),
             task = "simulation",
             reference_validated = validated,
             translation_file = sim_translation_file,
             translation_text = readLines(sim_translation_file, warn = FALSE),
             tables = tables,
             artifacts = artifacts,
             notes = notes)
      }))
  )
})
